const raw = items[0].json;
const body = raw.body || raw;
const email = (body.customer_email || body.user_email || '').trim();
const text = (body.message_text || body.status_message || '').trim();
const name = body.customer_name || '顧客';
const subject = body.subject || 'T&J 關心您上次的訂購';
if (!email || !text) {
  return [{ json: { skip: true, reason: 'missing email or text' } }];
}
return [{
  json: {
    skip: false,
    customer_email: email,
    subject,
    message_text: text,
    customer_name: name,
    html: `<p>${text.replace(/\n/g, '<br/>')}</p><p style="color:#888;font-size:12px">— T&J Cookies</p>`
  }
}];
